/**
 * Utility functions for the eval test project.
 */

/**
 * Greet someone by name.
 */
export function greet(name: string): string {
  return `Hello, ${name}!`;
}

/**
 * Greet someone formally with a title.
 */
export function greetFormal(name: string, title: string = "Sir/Madam"): string {
  return `Good day, ${title} ${name}. It is a pleasure to meet you.`;
}

/**
 * Add two numbers.
 */
export function add(a: number, b: number): number {
  return a + b;
}

