});

input.new_string:
import { describe, expect, test } from "bun:test";
import { greet, greetFormal, add } from "./utils";

describe("utils", () => {
  test("greet returns greeting message", () => {
    expect(greet("Alice")).toBe("Hello, Alice!");
  });

  test("greetFormal returns formal greeting with default title", () => {
    expect(greetFormal("Smith")).toBe(
      "Good day, Sir/Madam Smith. It is a pleasure to meet you."
    );
  });

  test("greetFormal returns formal greeting with custom title", () => {
    expect(greetFormal("Johnson", "Dr.")).toBe(
      "Good day, Dr. Johnson. It is a pleasure to meet you."
    );
  });

  test("add returns sum of two numbers", () => {
    expect(add(2, 3)).toBe(5);
  });
});

