/**
 * High-performance JSON Schema validator.
 * Supports a subset of JSON Schema Draft 7 with optimization for speed.
 */

export interface ValidationSchema {
  type?: string;
  required?: string[];
  minLength?: number;
  maxLength?: number;
  pattern?: string;
  enum?: unknown[];
  properties?: Record<string, ValidationSchema>;
  additionalProperties?: boolean;
}

export interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
}

export interface ValidationError {
  path: string;
  message: string;
}

/**
 * Validates a JSON object against a schema.
 * Optimized for performance with early exits and minimal allocations.
 */
export function validateJson(
  data: unknown,
  schema: ValidationSchema
): ValidationResult {
  const errors: ValidationError[] = [];
  validateValue(data, schema, "", errors);
  return {
    valid: errors.length === 0,
    errors,
  };
}

/**
 * Internal recursive validation function.
 */
function validateValue(
  value: unknown,
  schema: ValidationSchema,
  path: string,
  errors: ValidationError[]
): void {
  if (!schema) return;

  const currentPath = path || "root";

  // Type validation
  if (schema.type) {
    const actualType = getType(value);
    if (actualType !== schema.type) {
      errors.push({
        path: currentPath,
        message: `Expected type ${schema.type}, got ${actualType}`,
      });
      return; // Early exit on type mismatch
    }
  }

  // String validations
  if (typeof value === "string") {
    if (schema.minLength !== undefined && value.length < schema.minLength) {
      errors.push({
        path: currentPath,
        message: `String length ${value.length} is less than minimum ${schema.minLength}`,
      });
    }

    if (schema.maxLength !== undefined && value.length > schema.maxLength) {
      errors.push({
        path: currentPath,
        message: `String length ${value.length} exceeds maximum ${schema.maxLength}`,
      });
    }

    if (schema.pattern) {
      try {
        const regex = new RegExp(schema.pattern);
        if (!regex.test(value)) {
          errors.push({
            path: currentPath,
            message: `String does not match pattern ${schema.pattern}`,
          });
        }
      } catch (e) {
        errors.push({
          path: currentPath,
          message: `Invalid regex pattern: ${schema.pattern}`,
        });
      }
    }
  }

  // Enum validation
  if (schema.enum !== undefined) {
    if (!schema.enum.includes(value)) {
      errors.push({
        path: currentPath,
        message: `Value is not in enum: ${JSON.stringify(schema.enum)}`,
      });
    }
  }

  // Object validation
  if (typeof value === "object" && value !== null && schema.properties) {
    const obj = value as Record<string, unknown>;

    // Check required fields
    if (schema.required) {
      for (const field of schema.required) {
        if (!(field in obj)) {
          errors.push({
            path: `${currentPath}.${field}`,
            message: "Required field is missing",
          });
        }
      }
    }

    // Validate each property
    for (const [key, propValue] of Object.entries(obj)) {
      const propSchema = schema.properties[key];
      if (propSchema) {
        const propPath = currentPath === "root" ? key : `${currentPath}.${key}`;
        validateValue(propValue, propSchema, propPath, errors);
      } else if (schema.additionalProperties === false) {
        errors.push({
          path: `${currentPath}.${key}`,
          message: "Additional properties are not allowed",
        });
      }
    }
  }
}

/**
 * Determine the JSON type of a value.
 */
function getType(value: unknown): string {
  if (value === null) return "null";
  if (Array.isArray(value)) return "array";
  return typeof value;
}

/**
 * Comprehensive tests for JSON validator.
 */

import { describe, test, expect } from "bun:test";
import { validateJson } from "./json-validator";

describe("validateJson", () => {
  describe("type validation", () => {
    test("should validate string type", () => {
      const result = validateJson("hello", { type: "string" });
      expect(result.valid).toBe(true);
      expect(result.errors.length).toBe(0);
    });

    test("should validate number type", () => {
      const result = validateJson(42, { type: "number" });
      expect(result.valid).toBe(true);
    });

    test("should validate boolean type", () => {
      const result = validateJson(true, { type: "boolean" });
      expect(result.valid).toBe(true);
    });

    test("should validate object type", () => {
      const result = validateJson({}, { type: "object" });
      expect(result.valid).toBe(true);
    });

    test("should validate array type", () => {
      const result = validateJson([], { type: "array" });
      expect(result.valid).toBe(true);
    });

    test("should reject type mismatch", () => {
      const result = validateJson("hello", { type: "number" });
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBe(1);
      expect(result.errors[0].message).toContain("Expected type number");
    });

    test("should handle null type", () => {
      const result = validateJson(null, { type: "null" });
      expect(result.valid).toBe(true);
    });
  });

  describe("string validations", () => {
    test("should validate minLength", () => {
      const result = validateJson("hello", { type: "string", minLength: 3 });
      expect(result.valid).toBe(true);
    });

    test("should reject below minLength", () => {
      const result = validateJson("hi", { type: "string", minLength: 3 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("less than minimum");
    });

    test("should validate maxLength", () => {
      const result = validateJson("hello", { type: "string", maxLength: 10 });
      expect(result.valid).toBe(true);
    });

    test("should reject above maxLength", () => {
      const result = validateJson("hello", { type: "string", maxLength: 3 });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("exceeds maximum");
    });

    test("should validate pattern matching", () => {
      const result = validateJson("test123", {
        type: "string",
        pattern: "^[a-z]+[0-9]+$",
      });
      expect(result.valid).toBe(true);
    });

    test("should reject pattern mismatch", () => {
      const result = validateJson("123test", {
        type: "string",
        pattern: "^[a-z]+[0-9]+$",
      });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("does not match pattern");
    });

    test("should handle invalid regex pattern", () => {
      const result = validateJson("test", {
        type: "string",
        pattern: "[invalid(",
      });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("Invalid regex pattern");
    });
  });

  describe("enum validation", () => {
    test("should validate enum match", () => {
      const result = validateJson("red", { enum: ["red", "green", "blue"] });
      expect(result.valid).toBe(true);
    });

    test("should reject enum mismatch", () => {
      const result = validateJson("yellow", {
        enum: ["red", "green", "blue"],
      });
      expect(result.valid).toBe(false);
      expect(result.errors[0].message).toContain("not in enum");
    });

    test("should handle mixed type enums", () => {
      const result = validateJson(1, { enum: [1, "two", true, null] });
      expect(result.valid).toBe(true);
    });

    test("should reject mixed type enum mismatch", () => {
      const result = validateJson(2, { enum: [1, "two", true, null] });
      expect(result.valid).toBe(false);
    });
  });

  describe("object validation", () => {
    test("should validate required fields", () => {
      const schema = {
        type: "object",
        required: ["name", "email"],
        properties: {
          name: { type: "string" },
          email: { type: "string" },
        },
      };
      const result = validateJson(
        { name: "John", email: "john@example.com" },
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("should reject missing required field", () => {
      const schema = {
        type: "object",
        required: ["name", "email"],
        properties: {
          name: { type: "string" },
          email: { type: "string" },
        },
      };
      const result = validateJson({ name: "John" }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.path.includes("email"))).toBe(true);
    });

    test("should validate nested properties", () => {
      const schema = {
        type: "object",
        required: ["user"],
        properties: {
          user: {
            type: "object",
            required: ["name"],
            properties: {
              name: { type: "string" },
            },
          },
        },
      };
      const result = validateJson(
        { user: { name: "John" } },
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("should reject invalid nested properties", () => {
      const schema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            properties: {
              name: { type: "string" },
            },
          },
        },
      };
      const result = validateJson(
        { user: { name: 123 } },
        schema
      );
      expect(result.valid).toBe(false);
    });

    test("should handle additionalProperties false", () => {
      const schema = {
        type: "object",
        additionalProperties: false,
        properties: {
          name: { type: "string" },
        },
      };
      const result = validateJson({ name: "John", extra: "field" }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.some((e) => e.path.includes("extra"))).toBe(true);
    });

    test("should allow additionalProperties by default", () => {
      const schema = {
        type: "object",
        properties: {
          name: { type: "string" },
        },
      };
      const result = validateJson({ name: "John", extra: "field" }, schema);
      expect(result.valid).toBe(true);
    });
  });

  describe("edge cases", () => {
    test("should handle empty schema", () => {
      const result = validateJson({ any: "value" }, {});
      expect(result.valid).toBe(true);
    });

    test("should handle null value with no schema", () => {
      const result = validateJson(null, {});
      expect(result.valid).toBe(true);
    });

    test("should handle zero value", () => {
      const result = validateJson(0, { type: "number" });
      expect(result.valid).toBe(true);
    });

    test("should handle empty string with minLength 0", () => {
      const result = validateJson("", {
        type: "string",
        minLength: 0,
      });
      expect(result.valid).toBe(true);
    });

    test("should handle false value", () => {
      const result = validateJson(false, { type: "boolean" });
      expect(result.valid).toBe(true);
    });

    test("should accumulate multiple errors", () => {
      const schema = {
        type: "object",
        required: ["a", "b"],
        properties: {
          a: { type: "string" },
          b: { type: "number" },
        },
      };
      const result = validateJson({}, schema);
      expect(result.valid).toBe(false);
      expect(result.errors.length).toBeGreaterThanOrEqual(2);
    });
  });

  describe("complex schemas", () => {
    test("should validate complex user object", () => {
      const schema = {
        type: "object",
        required: ["id", "email"],
        properties: {
          id: { type: "number" },
          email: { type: "string", pattern: "^.+@.+\\..+$" },
          name: { type: "string", minLength: 1, maxLength: 100 },
          role: { enum: ["admin", "user", "guest"] },
          profile: {
            type: "object",
            properties: {
              bio: { type: "string", maxLength: 500 },
              avatar: { type: "string" },
            },
          },
        },
      };
      const result = validateJson(
        {
          id: 1,
          email: "user@example.com",
          name: "John Doe",
          role: "user",
          profile: { bio: "A user", avatar: "https://example.com/avatar.jpg" },
        },
        schema
      );
      expect(result.valid).toBe(true);
    });

    test("should provide detailed error paths in complex schemas", () => {
      const schema = {
        type: "object",
        properties: {
          user: {
            type: "object",
            required: ["email"],
            properties: {
              email: { type: "string" },
            },
          },
        },
      };
      const result = validateJson({ user: {} }, schema);
      expect(result.valid).toBe(false);
      expect(result.errors[0].path).toContain("user");
      expect(result.errors[0].path).toContain("email");
    });
  });

  describe("performance characteristics", () => {
    test("should validate large objects efficiently", () => {
      const largeObj: Record<string, unknown> = {};
      for (let i = 0; i < 1000; i++) {
        largeObj[`field${i}`] = `value${i}`;
      }

      const schema = { type: "object" };
      const start = performance.now();
      const result = validateJson(largeObj, schema);
      const elapsed = performance.now() - start;

      expect(result.valid).toBe(true);
      expect(elapsed).toBeLessThan(100); // Should complete in less than 100ms
    });

    test("should handle deeply nested structures", () => {
      let nested: Record<string, unknown> = { value: "deep" };
      for (let i = 0; i < 50; i++) {
        nested = { nested };
      }

      const schema = { type: "object" };
      const result = validateJson(nested, schema);
      expect(result.valid).toBe(true);
    });
  });
});

