/**
 * Main entry point for the rp1 eval test project.
 */

import { greet, validateJson } from "./utils";

const name = process.argv[2] ?? "World";
console.log(greet(name));

// Example: JSON validator usage
const userSchema = {
  type: "object" as const,
  required: ["id", "email"],
  properties: {
    id: { type: "number" },
    email: { type: "string", pattern: "^.+@.+\\..+$" },
    name: { type: "string", minLength: 1, maxLength: 100 },
  },
};

const validUser = {
  id: 1,
  email: "user@example.com",
  name: "John Doe",
};

const result = validateJson(validUser, userSchema);
console.log("\nJSON Validation Example:");
console.log("Schema:", userSchema);
console.log("Data:", validUser);
console.log("Valid:", result.valid);
if (!result.valid) {
  console.log("Errors:", result.errors);
}

